common:
vec3 aces(vec3 x){
return clamp((x*(2.51*x+.03))/(x*(2.43*x+.59)+.14),0.,1.);
}
float bayer4(vec2 px){
int x=int(mod(px.x,4.));
int y=int(mod(px.y,4.));
int i=x+y*4;
const int m[16]=int[16](0,8,2,10,12,4,14,6,3,11,1,9,15,7,13,5);
return(float(m[i])+.5)/16.;
}
float easeOutCubic(float x){
float f=1.-x;
return 1.-f*f*f;
}
float hash11(float p){
uint x=floatBitsToUint(p);
x=((x>>16u)^x)*2146503469u;
x=((x>>16u)^x)*2146503469u;
x=(x>>16u)^x;
return float(x>>8u)*(1./16777216.);
}
vec2 pixUV(vec2 fragCoord,vec2 res){
return(floor(fragCoord)+.5)/res;
}
vec3 retroQuantize(vec3 col,const vec3 pal[16],int n,vec2 px){
float d=bayer4(px)-.5;
vec3 c=col+d*(1./float(n));
int best=0;
float bd=1e9;
for(int i=0;i<16;i++){
if(i>=n)break;
vec3 diff=c-pal[i];
float dd=dot(diff,diff);
if(dd<bd){bd=dd;best=i;}
}
return pal[best];
}
vec3 toSRGB(vec3 c){
c=max(c,vec3(0.));
return mix(1.055*pow(c,vec3(1./2.4))-.055,c*12.92,step(c,vec3(.0031308)));
}
vec3 vignette(vec3 c,vec2 uv,float strength){
float d=distance(uv,vec2(.5));
return c*(1.-strength*smoothstep(.35,.85,d));
}
float wrapTime(float t,float period){
return t-period*floor(t/period);
}
vec3 retroFinalize(vec3 col,vec2 uv,vec2 fragCoord,const vec3 pal[16],int n){
vec3 q=retroQuantize(clamp(col,0.,1.),pal,n,fragCoord);
float d=distance(uv,vec2(.5));
return q*(1.-.25*smoothstep(.45,.9,d));
}
const vec3 PALETTE[16]=vec3[16](
vec3(.063,.063,.078),
vec3(.078,.204,.231),
vec3(.18,.18,.22),
vec3(.949,.918,.827),
vec3(.949,.651,.702),
vec3(.11,.29,.32),
vec3(.16,.4,.43),
vec3(.22,.51,.54),
vec3(.09,.14,.16),
vec3(.13,.13,.16),
vec3(.24,.24,.29),
vec3(.85,.8,.69),
vec3(.76,.5,.56),
vec3(.98,.96,.9),
vec3(.98,.85,.88),
vec3(.055,.055,.066)
);
const int PALETTE_N=16;
vec3 finalize(vec3 col,vec2 uv){
#ifdef PROFILE_RETRO
return retroFinalize(col,uv,gl_FragCoord.xy,PALETTE,PALETTE_N);
#else
col=aces(col);
col=vignette(col,uv,.25);
return toSRGB(col);
#endif
}
const vec3 WH_TEAL_D=vec3(.145,.31,.314);
const vec3 WH_TEAL_L=vec3(.22,.451,.455);
const vec3 WH_BLACK=vec3(.031,.027,.039);
const float WH_FLOOR=28.;
vec3 floorBackground(vec2 px,vec2 res){
float v=clamp((px.y/res.y-.12)/.76,0.,1.);
vec3 col=mix(WH_TEAL_D,WH_TEAL_L,step(bayer4(px),v));
if(px.y>=WH_FLOOR-3.&&px.y<WH_FLOOR-1.)col=WH_BLACK*.7;
return col;
}
const vec3 OC_PAL[16]=vec3[16](
vec3(.02,.02,.04),
vec3(.85,.45,.12),
vec3(.95,.85,.62),
vec3(.16,.07,.05),
vec3(.02,.02,.04),
vec3(.02,.02,.04),
vec3(.02,.02,.04),
vec3(.02,.02,.04),
vec3(.02,.02,.04),
vec3(.02,.02,.04),
vec3(.02,.02,.04),
vec3(.02,.02,.04),
vec3(.02,.02,.04),
vec3(.02,.02,.04),
vec3(.02,.02,.04),
vec3(.02,.02,.04)
);
const float OC_CELL=4.;
const int OC_EAR=1;
const int OC_AIR=2;
const int OC_BLINK=4;
int orangeCat(ivec2 c,int k,int tb,int hip,ivec2 look,int flags){
const int TOP[3]=int[3](4,3,1);
int top=TOP[k];
int wide=k==2?1:0;
ivec2 b=c-ivec2(hip,0);
int id=0;
bool fur=b.y>=0&&b.y<=top&&b.x>=-5-wide&&b.x<=4+wide&&
!(b.y==0&&(b.x<-3-wide||b.x>2+wide));
for(int i=0;i<5;i++){
if(b.x==4+wide+i&&b.y==tb+(i*i)/4)fur=true;
}
if(fur){
bool band=b.y>=1&&b.y<=top;
if(band&&b.x>=-1&&b.x<=2)id=2;
else if(band&&(b.x+6)%3==1)id=3;
else id=1;
}
if((flags&OC_AIR)!=0&&c.y==-1&&(c.x==-3||c.x==-2||c.x==1||c.x==2))id=1;
int hb=top+1;
if(c.y>=hb&&c.y<=hb+5&&c.x>=-4&&c.x<=3){
id=1;
if(c.y==hb+3+look.y&&(c.x==-2+look.x||c.x==1+look.x))id=(flags&OC_BLINK)!=0?1:3;
else if(c.x==0&&c.y==hb+2)id=2;
}
int ey=c.y-hb-6;
int tipL=k==2?-4:-3;
int tipR=(k==2||(flags&OC_EAR)!=0)?2:1;
if(ey==0&&(c.x==-4||c.x==-3||c.x==1||c.x==2))id=1;
if(ey==1&&(c.x==tipL||c.x==tipR))id=1;
return id;
}
int orangeCatPixel(vec2 px,vec2 o,int k,int tb,int hip,ivec2 look,int flags){
ivec2 g=ivec2(floor((px-o)/OC_CELL));
if(g.x<-8||g.x>11||g.y<-2||g.y>14)return-1;
int id=orangeCat(g,k,tb,hip,look,flags);
if(id>0)return id;
if(g.y<0&&(flags&OC_AIR)==0)return-1;
if(orangeCat(g+ivec2(1,0),k,tb,hip,look,flags)>0||
orangeCat(g-ivec2(1,0),k,tb,hip,look,flags)>0||
orangeCat(g+ivec2(0,1),k,tb,hip,look,flags)>0||
orangeCat(g-ivec2(0,1),k,tb,hip,look,flags)>0)return 0;
return-1;
}
bool mothAt(vec2 px,vec2 pos,bool wingsUp){
ivec2 q=ivec2(floor(px))-ivec2(pos);
bool body=q.x>=0&&q.x<=1&&q.y>=0&&q.y<=1;
bool wing=(q.x==-2||q.x==-1||q.x==2||q.x==3)&&
(wingsUp?(q.y==1||q.y==2):(q.y==-1||q.y==0));
return body||wing;
}
vec3 whiskerFinalize(vec3 bg,int idx,vec2 fragCoord,vec2 res){
vec2 uv=fragCoord/res;
return idx>=0?retroFinalize(OC_PAL[idx],uv,fragCoord,OC_PAL,8):finalize(bg,uv);
}

scenes.wake:
void mainImage(out vec4 fragColor,in vec2 fragCoord){
vec2 res=iResolution.xy;
vec2 px=fragCoord;
int ix=int(px.x);
int fy=146-int(px.y);
const vec3 pal[16]=vec3[16](
vec3(.004,.02,.03),
vec3(.01,.05,.06),
vec3(.016,.08,.1),
vec3(.03,.13,.15),
vec3(.05,.19,.21),
vec3(0.,0.,0.),
vec3(.85,.45,.1),
vec3(.92,.92,.88),
vec3(.008,.035,.045),
vec3(.04,.16,.18),
vec3(.07,.23,.25),
vec3(.7,.35,.08),
vec3(.95,.65,.25),
vec3(.75,.75,.72),
vec3(.02,.1,.12),
vec3(.06,.21,.23)
);
float e=easeOutCubic(clamp(uSceneProgress*5.,0.,1.));
int yOff=1-int(floor(e+.5));
float vis=e;
float depth=clamp(px.y/res.y,0.,1.);
vec3 col=(bayer4(px)<depth)?pal[3]:pal[2];
vec2 cell=floor(px/vec2(32.,24.));
float h=hash11(cell.x*7.31+cell.y*113.7+floor(uBar)*17.13);
vec2 sp=(cell+vec2(hash11(h+1.),hash11(h+2.)))*vec2(32.,24.);
if(h>.82&&length(px-(sp+vec2(.5)))<.6&&fract(uBar)>.5)col=pal[4];
bool show=bayer4(px)<vis;
if(show&&(fy==120||fy==121)&&ix>=38&&ix<=58)col=pal[1];
float tt=wrapTime(uSceneTime,.9375);
float sw=(.5-.5*cos(6.2831853*tt))*clamp(uSceneProgress*2.-.6,0.,1.);
int tj=39-ix;
if(show&&tj>=0&&tj<=9){
int lift=int(floor(sw*3.*(float(tj)/9.)+.5));
int dy=fy-(118+yOff-lift);
if(dy>=0&&dy<2)col=pal[6];
else if(dy==-1||dy==2)col=pal[5];
}
const uint CAT[16]=uint[16](
0u,3120u,3640u,4088u,4088u,4088u,4088u,8184u,
16380u,16380u,16382u,16382u,16382u,16382u,16380u,8184u
);
int lx=ix-40;
int r=fy-103-yOff;
if(show&&lx>=0&&lx<16&&r>=0&&r<15){
int m0=int((CAT[r]>>(15-lx))&1u);
if(m0==1){
int m1=(lx<15)?int((CAT[r]>>(14-lx))&1u):0;
int m2=(lx>0)?int((CAT[r]>>(16-lx))&1u):0;
int m3=(r<15)?int((CAT[r+1]>>(15-lx))&1u):0;
int m4=(r>0)?int((CAT[r-1]>>(15-lx))&1u):0;
int interior=m1*m2*m3*m4;
bool blink=fract(uSceneTime*.25)<.1;
if(lx==11&&r==4&&!blink){
col=pal[5];
}else if(interior==1){
if(lx>=9&&lx<=12&&r>=7&&r<=12)col=pal[7];
else col=pal[6];
}else{
col=pal[5];
}
}
}
vec2 uv=pixUV(fragCoord,res);
fragColor=vec4(retroFinalize(col,uv,fragCoord,pal,16),1.);
}

scenes.idle:
void mainImage(out vec4 fragColor,in vec2 fragCoord){
vec2 res=iResolution.xy;
vec2 px=fragCoord.xy;
int ft=int(floor(uSceneTime*12.));
int flags=0;
if(ft==8||ft==9)flags|=OC_BLINK;
if(ft==14||ft==15)flags|=OC_EAR;
int tb=1+int(round(2.*(.5-.5*cos(float(ft)*6.2831853/22.5))));
ivec2 look=ft>=19?ivec2(-1,0):ivec2(0);
int idx=orangeCatPixel(px,vec2(240.,WH_FLOOR),0,tb,0,look,flags);
if(ft>=12){
vec2 moth=vec2(152.-16.*float(22-ft),50.+floor(5.*sin(float(ft-22)*.55)));
if(mothAt(px,moth,ft%2==0))idx=2;
}
fragColor=vec4(whiskerFinalize(floorBackground(px,res),idx,fragCoord,res),1.);
}

scenes.hunt:
void mainImage(out vec4 fragColor,in vec2 fragCoord){
vec2 res=iResolution.xy;
vec2 px=fragCoord.xy;
int f=int(floor(uSceneTime*12.));
int k=0;
int tb=1;
int hip=0;
int flags=0;
ivec2 look=ivec2(-1,0);
float ox=240.;
float oy=WH_FLOOR;
const int WAG[4]=int[4](0,2,3,1);
if(f<6){
if(f>=3)flags|=OC_EAR;
}else if(f<8){
k=1;
}else if(f<24){
k=2;
tb=WAG[f%4];
if(f>=16)hip=((f/2)%2==0)?-1:1;
}else if(f<30){
float s=float(f-23)/7.;
k=2;
tb=3;
flags|=OC_AIR;
ox=floor(mix(240.,160.,s));
oy=WH_FLOOR+floor(24.*sin(3.14159265*s));
}else if(f<32){
k=2;
ox=160.;
tb=0;
look=ivec2(-1,1);
}else if(f<34){
k=1;
ox=160.;
look=ivec2(-1,1);
}else if(f<41){
ox=160.;
look=ivec2(-1,1);
tb=1+int(round(sin(float(f-34)*.9)));
}else{
ox=160.;
look=ivec2(0);
}
int idx=orangeCatPixel(px,vec2(ox,oy),k,tb,hip,look,flags);
float mf=float(f);
vec2 moth=vec2(152.+floor(4.*sin(mf*.9)),50.+floor(5.*sin(mf*.55)));
if(f>=26){
float a=float(min(f,31)-25);
float b=float(max(f-31,0));
moth+=vec2(-8.*a-1.*b,9.*a+4.*b);
}
if(mothAt(px,moth,f%2==0))idx=2;
fragColor=vec4(whiskerFinalize(floorBackground(px,res),idx,fragCoord,res),1.);
}

